def feats2(g,r0,r1,c0,c1):
    blk=[row[c0:c1] for row in g[r0:r1]]
    flat=[x for row in blk for x in row]
    import collections
    cnt=collections.Counter(flat)
    f={}
    for c in range(10): f[f'c{c}']=cnt.get(c,0); f[f'h{c}']=1 if cnt.get(c,0) else 0
    # components of nonzero within block (4-conn)
    seen=set(); comp=0
    H,W=len(blk),len(blk[0])
    for i in range(H):
        for j in range(W):
            if blk[i][j]!=0 and (i,j) not in seen:
                comp+=1; st=[(i,j)]; seen.add((i,j))
                while st:
                    a,b=st.pop()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and blk[x][y]!=0 and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
    f['comp']=comp
    f['comp1']=sum(1 for x in range(10) if cnt.get(x,0)>0)
    f['sum']=sum(flat); f['nz']=sum(x!=0 for x in flat)
    f['diag_pairs']=sum(1 for i in range(H-1) for j in range(W-1) if blk[i][j]==blk[i+1][j+1]!=0 or blk[i][j+1]==blk[i+1][j]!=0)
    f['adj_same']=sum(1 for i in range(H) for j in range(W-1) if blk[i][j]==blk[i][j+1]!=0)+sum(1 for i in range(H-1) for j in range(W) if blk[i][j]==blk[i+1][j]!=0)
    return f
