def bres(r0,c0,r1,c1):
    cells=[]; dr=abs(r1-r0); dc=abs(c1-c0)
    sr=1 if r1>r0 else -1; sc=1 if c1>c0 else -1
    err=dr-dc; r,c=r0,c0
    while True:
        cells.append((r,c))
        if (r,c)==(r1,c1): break
        if 2*err> -dc: err-=dc; r+=sr
        if 2*err< dr: err+=dr; c+=sc
    return cells
def blocks(cells):
    out=set()
    for r,c in cells:
        i=min(r//2,2); j=min(c//2,2)
        out.add((i,j))
    return out
