from collections import Counter
def feats_g(g):
    f={}
    cnt=Counter(v for row in g for v in row)
    for v in range(10): f[f'c{v}']=cnt[v]
    f['ncol']=len([v for v in cnt if v not in(0,)])
    f['spec']=sum(cnt[v] for v in cnt if v not in (0,1))
    f['maxc']=max(cnt.values())
    # connected components of 0s and of nonzero, 4-conn
    def ncomp(target):
        seen=set(); n=0
        for r in range(7):
            for c in range(7):
                if (r,c) in seen or g[r][c] not in target: continue
                n+=1; q=deque([(r,c)]); seen.add((r,c))
                while q:
                    a,b=q.popleft()
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<7 and 0<=y<7 and (x,y) not in seen and g[x][y] in target:
                            seen.add((x,y)); q.append((x,y))
        return n
    f['nc0']=ncomp({0}); f['ncnz']=ncomp(set(range(1,10))); f['nc1']=ncomp({1})
    # 2x2 all-zero blocks, all-same blocks
    za=sa=0
    for i in range(3):
        for j in range(3):
            vals={g[2*i+dr][2*j+dc] for dr in range(2) for dc in range(2)}
            if vals=={0}: za+=1
            if len(vals)==1: sa+=1
    f['zblocks']=za; f['sblocks']=sa
    return f
